use crossmool::{sm2,sm4};use hex;use serde_json::Value;
fn main(){let ref_data:Value=serde_json::from_str("{\"cross_enc\": \"0438567bf30a7d4032a4a6ae923532bd6fe2498e1555efbdd8fea5ab2ac94c517bc2402484de05aa610e945d7ad4d1b240ba5e6e53bd5484212f9dbd737fd6748ea94a1e97df1712f03f81aaff676cd273d800938440b79ee989f7212efee15e51760e3ca31629bf9f8ee90fc7ab8956a4515ba4f565a1f71f5b1625da051ad44351b2d698b7ada02e3a63168ce8bc2328ff\", \"cross_sig\": \"3044022038778f329bd0b61747bdbedbe65f62c43503cae48aeb39f4c54716154165d3240220366c79abd3ca2c9faeac61b1ff48b338625bbb54091a80fcc4291c8021057594\", \"cross_sm4\": \"86887d44a685f354e7504178fd7aff22aa845d5a77bab2af4b1f8313b4503ece478a3c766925cc1919833a9c8d6b95abdf3d79b3a7834170ef6bb47daf6f7fab86b2a17279d35fdd975b30e8c9\"}").unwrap();let m="Hello, 这是跨语言国密互通性测试数据";let mb=m.as_bytes();let mut r=serde_json::json!({});
if let Some(cs)=ref_data["cross_enc"].as_str(){match sm2::decrypt_with_private_pem_hex("-----BEGIN PRIVATE KEY-----\nMIGHAgEAMBMGByqGSM49AgEGCCqBHM9VAYItBG0wawIBAQQgsnPvQ8aGbdLIuKAwN0jkXdE1Vz3bABpHFB/48g8qmwOhRANCAATH4HBY+2Li2kwFPaEMN69FR2UNkJLyYOpDBLGNwIRYVsU5sxPeC2dsIIqZ4hx42+5BDjgFrbtCtC/ti1dEb3NW\n-----END PRIVATE KEY-----\n",cs){Ok(d)=>r["enc"]=serde_json::json!(if String::from_utf8_lossy(&d)==m{"PASS"}else{"FAIL"}),Err(e)=>r["enc"]=serde_json::json!(format!("FAIL:{}",e))}}
if let Some(ss)=ref_data["cross_sig"].as_str(){if let Ok(sb)=hex::decode(ss){match sm2::verify_with_public_pem(mb,&sb,"-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoEcz1UBgi0DQgAEGSwAD63T0tQL6NRzS5G7/hMW9DkHcBT/2FlZ4C2u7DzL7Iw3htvEMaq4LmNqCeC/dS52D9NOUSq6lMUgPWFyJg==\n-----END PUBLIC KEY-----\n"){Ok(ok)=>r["sig"]=serde_json::json!(if ok{"PASS"}else{"FAIL"}),Err(e)=>r["sig"]=serde_json::json!(format!("FAIL:{}",e))}}}
if let Some(sc)=ref_data["cross_sm4"].as_str(){let sk=hex::decode("0123456789abcdeffedcba9876543210").unwrap();match sm4::decrypt_gcm_to_string(&sk,sc){Ok(sd)=>r["sm4"]=serde_json::json!(if sd==m{"PASS"}else{"FAIL"}),Err(e)=>r["sm4"]=serde_json::json!(format!("FAIL:{}",e))}}
if let(Some(cs),Some(ss))=(ref_data["cross_enc"].as_str(),ref_data["cross_sig"].as_str()){if let(Ok(d2),Ok(sb))=(sm2::decrypt_with_private_pem_hex("-----BEGIN PRIVATE KEY-----\nMIGHAgEAMBMGByqGSM49AgEGCCqBHM9VAYItBG0wawIBAQQgsnPvQ8aGbdLIuKAwN0jkXdE1Vz3bABpHFB/48g8qmwOhRANCAATH4HBY+2Li2kwFPaEMN69FR2UNkJLyYOpDBLGNwIRYVsU5sxPeC2dsIIqZ4hx42+5BDjgFrbtCtC/ti1dEb3NW\n-----END PRIVATE KEY-----\n",cs),hex::decode(ss)){let d2s=String::from_utf8_lossy(&d2);let o2=sm2::verify_with_public_pem(&d2,&sb,"-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoEcz1UBgi0DQgAEGSwAD63T0tQL6NRzS5G7/hMW9DkHcBT/2FlZ4C2u7DzL7Iw3htvEMaq4LmNqCeC/dS52D9NOUSq6lMUgPWFyJg==\n-----END PUBLIC KEY-----\n").unwrap_or(false);r["esvd"]=serde_json::json!(if d2s==m&&o2{"PASS"}else{"FAIL"});}}
println!("{}",serde_json::to_string(&r).unwrap());}